from pathlib import Path
import re

from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_LINE_SPACING
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Inches, Pt, RGBColor


ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "Detailed_Discussion_Chapter.docx"


def configure(doc):
    section = doc.sections[0]
    section.top_margin = Inches(0.8)
    section.bottom_margin = Inches(0.8)
    section.left_margin = Inches(1.0)
    section.right_margin = Inches(1.0)
    normal = doc.styles["Normal"]
    normal.font.name = "Times New Roman"
    normal.font.size = Pt(11)
    normal.paragraph_format.line_spacing = 1.5
    for name, size in (("Title", 18), ("Heading 1", 15), ("Heading 2", 13), ("Heading 3", 11.5)):
        style = doc.styles[name]
        style.font.name = "Times New Roman"
        style.font.size = Pt(size)
        style.font.bold = True
        style.font.color.rgb = RGBColor(31, 78, 121)
        style.paragraph_format.keep_with_next = True
        style.paragraph_format.space_before = Pt(10)
        style.paragraph_format.space_after = Pt(5)
    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    footer.add_run("Discussion | Domain-Aware Promoter Prediction")


def body(doc, text):
    p = doc.add_paragraph(text)
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.first_line_indent = Inches(0.3)
    p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    p.paragraph_format.space_after = Pt(6)
    return p


def bullet(doc, text):
    p = doc.add_paragraph(style="List Bullet")
    p.add_run(text)
    p.paragraph_format.line_spacing = 1.15
    p.paragraph_format.space_after = Pt(3)


def build():
    doc = Document()
    configure(doc)

    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = p.add_run("CHAPTER 5\nDISCUSSION")
    run.bold = True
    run.font.name = "Times New Roman"
    run.font.size = Pt(18)
    run.font.color.rgb = RGBColor(31, 78, 121)

    body(doc, "The present study developed and evaluated a leakage-aware computational framework for promoter recognition across Bacteria, Archaea, and Eukaryota. Its central premise was that promoter prediction should account for both conserved sequence-learning principles and taxon-dependent promoter organization. The final systems therefore combined domain-specialized neural networks, organism-specific engineered features, multi-seed probability averaging, and validation-selected decision thresholds. The findings demonstrate that promoter and non-promoter sequences can be separated with substantial predictive accuracy across all three domains, but they also reveal meaningful differences in domain difficulty, error profile, useful feature representation, and the benefit obtained from hybrid modeling. This chapter interprets those findings in relation to the biological and computational objectives of the research, considers their methodological significance, and defines the limits within which the results can be generalized.")

    doc.add_heading("5.1 Interpretation of the principal findings", level=1)
    body(doc, "The three-seed neural ensembles achieved Matthews correlation coefficient (MCC) values of 0.617 for Bacteria, 0.842 for Archaea, and 0.708 for Eukaryota. After neural probabilities were combined with Random Forest predictions, the corresponding MCC values increased to 0.624, 0.844, and 0.723. The positive MCC values across every domain show that the classifiers learned relationships involving all four outcomes of binary classification rather than obtaining apparently favorable accuracy through majority-class prediction. This is particularly important because the organism-level datasets were not uniformly balanced, even though the complete dataset contained nearly equal numbers of promoter and non-promoter records.")
    body(doc, "Archaea achieved the strongest overall discrimination, with a final hybrid ROC-AUC of 0.977 and PR-AUC of 0.965. Eukaryota ranked second, with hybrid ROC-AUC of 0.918 and PR-AUC of 0.939, whereas Bacteria achieved ROC-AUC of 0.879 and PR-AUC of 0.869. These values indicate that each final model assigned higher scores to promoter sequences than to non-promoter sequences with useful consistency, even where the threshold-dependent sensitivity was lower. The ranking metrics are especially informative because they evaluate the ordering of predicted probabilities over many possible thresholds rather than only at one operating point.")
    body(doc, "The observed domain ordering should not be interpreted as a direct biological statement that archaeal promoters are universally easier to recognize than bacterial or eukaryotic promoters. Each domain differed in species composition, sequence-window length, sample size, database source, and negative-example construction. The archaeal result may reflect a relatively consistent signal in the selected −80 to +20 promoter windows, a favorable relationship between the positive and negative sampling protocols, or strong recurring oligomer patterns. Conversely, the bacterial result combined a larger E. coli subset with a much smaller B. subtilis subset and therefore required one domain system to accommodate distinct Gram-negative and Gram-positive promoter contexts. Performance differences are consequently properties of the present datasets and experimental design, not immutable rankings of biological complexity.")

    doc.add_heading("5.2 Significance of domain-specialized modeling", level=1)
    body(doc, "The domain-specialized strategy was supported by the large differences in sequence length and validation-selected operating threshold. Bacterial sequences were 80–81 nucleotides, archaeal sequences were 100 nucleotides, and eukaryotic sequences were 251 nucleotides. Padding every sequence to a common maximum could have introduced unnecessary empty context and encouraged a unified model to use length or padding patterns as shortcuts. Retaining natural domain lengths allowed the convolutional filters to operate at biologically relevant scales and reduced avoidable computation. It also ensured that differences in input organization were treated as part of model design rather than hidden within a single representation.")
    body(doc, "The selected architectures also reflected the character of the sequence windows. Multi-scale CNNs were used for Bacteria and Archaea, where relatively short sequences may contain several local regulatory elements whose width and spacing differ. Parallel convolutional kernels can detect signals at multiple resolutions without requiring a very deep model. The Residual CNN was selected for the much larger eukaryotic dataset, where stacked residual blocks can learn increasingly complex local combinations while maintaining stable gradient flow. The completed results show that both choices produced useful classifiers; however, they do not establish that these architectures are globally superior to all implemented alternatives because a complete multi-seed comparison of every candidate architecture was not performed.")
    body(doc, "The study initially aimed toward broad, domain-aware prediction, but the completed empirical findings favor specialization at the current stage. Separate models avoid forcing E. coli, B. subtilis, mammals, plants, and Archaea into one decision boundary. This is biologically reasonable because promoter consensus elements, transcriptional machinery, nucleotide composition, motif orientation, and spacing constraints differ among these groups. At the same time, specialization creates a practical dependency: the correct domain or organism group must be known before prediction. A future unified model could reduce this dependency, but it would need to demonstrate that shared representation learning improves generalization without allowing domain identity to dominate the promoter decision.")

    doc.add_heading("5.3 Interpretation of domain-specific error patterns", level=1)
    doc.add_heading("5.3.1 Bacterial classification", level=2)
    body(doc, "The bacterial neural ensemble showed high specificity (0.905) and precision (0.860) but lower sensitivity (0.692). Its validation-selected threshold of 0.876 was considerably higher than 0.50, indicating that the model required strong accumulated evidence before assigning the promoter label. This conservative decision rule reduced false promoter calls but produced 165 false negatives in the neural test evaluation. After hybridization, sensitivity increased to 0.723, although specificity decreased to 0.888. The change shows that engineered sequence composition rescued some promoter sequences that did not receive sufficiently high neural scores, while also moving a number of non-promoters across the decision boundary.")
    body(doc, "Several factors may explain the bacterial difficulty. First, the finalized B. subtilis subset contained only 1,441 sequences, compared with 6,573 for E. coli, resulting in unequal evidence for the two organisms. Second, bacterial promoters are influenced by sigma-factor specificity and can contain variable spacing and non-canonical motifs. Third, genomic coding-region negatives may share GC composition and short oligomers with promoters, making them more challenging than artificial shuffled controls. This challenge is methodologically desirable because it reduces the likelihood that a classifier succeeds through simplistic genomic-composition differences, but it can lower measured sensitivity.")

    doc.add_heading("5.3.2 Archaeal classification", level=2)
    body(doc, "The archaeal system displayed the most balanced and consistently strong error profile. The neural ensemble achieved sensitivity of 0.871 and specificity of 0.960, and the hybrid increased sensitivity to 0.904 while specificity became 0.943. The hybrid therefore exchanged 18 additional false-positive decisions for 18 fewer false negatives, leaving the overall accuracy unchanged at 0.930 while slightly improving MCC and materially improving ROC-AUC and PR-AUC. This illustrates why relying on accuracy alone would have hidden an important change in model behavior. The hybrid ranked sequences more effectively and recovered more promoters, even though the total number of correct classifications did not change.")
    body(doc, "The strong archaeal result suggests that the chosen 100-nt windows contain a learnable and relatively stable promoter signal. Nevertheless, caution is necessary. The archaeal dataset aggregated H. volcanii, S. solfataricus, and T. kodakarensis, and the saved records were treated as a combined group. Moreover, the repository lacked the correctly labelled intermediate archaeal CD-HIT clustering artifact. The finalized files were audited and the six cross-label reverse-complement groups were quarantined, but the missing intermediate limits full reconstruction of the raw-to-finalized transformation. Strong predictive performance does not remove this provenance limitation.")

    doc.add_heading("5.3.3 Eukaryotic classification", level=2)
    body(doc, "The eukaryotic neural model combined high specificity (0.939), precision (0.930), and PR-AUC (0.932) with lower sensitivity (0.761). This profile indicates that predicted promoters were usually reliable, but approximately one quarter of true promoters did not exceed the selected probability threshold. Eukaryotic promoters are structurally heterogeneous: some contain recognizable core elements, while others depend on dispersed sequence composition and broader regulatory context. Combining human, mouse, and Arabidopsis further expands this heterogeneity. The model was therefore required to recognize promoter evidence shared across two mammals and a plant while operating on a single 251-nt representation.")
    body(doc, "The eukaryotic hybrid produced the clearest overall improvement. Accuracy increased from 0.847 to 0.855, MCC from 0.708 to 0.723, ROC-AUC from 0.911 to 0.918, and PR-AUC from 0.932 to 0.939. Both sensitivity and specificity improved. This simultaneous gain suggests that neural and engineered representations captured complementary aspects of eukaryotic promoter organization rather than merely shifting the operating threshold toward one class. The neural network could learn spatial motif combinations directly, whereas the Random Forest contributed explicit oligomer-frequency and organism-selected positional or stability information. Their integration reduced both false-positive and false-negative error rates.")

    doc.add_heading("5.4 Contribution of multi-seed probability averaging", level=1)
    body(doc, "Probability averaging improved the neural MCC in all three domains relative to the original seed-2025 model: by 0.056 in Bacteria, 0.032 in Archaea, and 0.013 in Eukaryota. The largest gain occurred in the bacterial task, which also had the smallest combined training set and greatest apparent sensitivity to initialization. This pattern is consistent with the general role of ensembling as a variance-reduction mechanism. Independently initialized networks can converge to different local solutions and assign different confidence to borderline sequences. Averaging preserves evidence that is stable across seeds while reducing the influence of idiosyncratically extreme predictions.")
    body(doc, "The smaller eukaryotic gain does not imply that ensembling was unnecessary. With a larger training set, individual models are expected to be more stable, leaving less variance for averaging to remove. Even a modest MCC increase can be meaningful when evaluated across 12,100 test records. Moreover, PR-AUC improved in all domains, suggesting that probability averaging enhanced ranking as well as the final thresholded decision. The ensemble threshold was selected from averaged validation probabilities rather than borrowed from an individual seed, which maintained separation between model development and final evaluation.")
    body(doc, "A limitation of the three-seed approach is that it estimates only a small portion of initialization variability. Three seeds provide stronger evidence than a single run but do not characterize the full distribution of possible trained models. The component networks also shared an architecture and data partition, so their errors were correlated. Greater diversity might be obtained from architecture-level ensembles, cross-validation folds, or models trained on complementary feature representations. Such extensions would require additional computation and a prespecified comparison protocol to avoid excessive selection on the validation set.")

    doc.add_heading("5.5 Meaning of the organism-specific feature-ablation findings", level=1)
    body(doc, "The feature-ablation results demonstrated that no single handcrafted representation was optimal across all organisms. E. coli and the combined archaeal group retained directional 1–4-mer features; B. subtilis selected canonical 1–6-mers; human selected directional 1–6-mers; mouse selected canonical 1–6-mers plus position-specific descriptors; and Arabidopsis selected canonical 1–6-mers, positional features, and dinucleotide stability. This heterogeneity is a central finding because it supports the thesis premise that promoter recognition contains shared principles but is expressed through taxon-dependent sequence organization.")
    body(doc, "Directional k-mers preserve transcriptional orientation. Their selection for E. coli, Archaea, and human suggests that forward-strand motif orientation or asymmetric sequence context may be informative in these groups. Canonical k-mers collapse each oligomer with its reverse complement, reducing dimensionality and emphasizing composition independent of strand. Their selection for B. subtilis, mouse, and Arabidopsis suggests that orientation-invariant patterns provided useful generalization for these datasets. These interpretations describe associations with predictive performance; they do not prove that a particular biological motif or transcription factor caused the improvement.")
    body(doc, "Position-specific features were retained for mouse and Arabidopsis but not for the other groups. Because promoter motifs are often meaningful relative to the TSS, their value in these organisms is biologically plausible. Nevertheless, position-specific encoding can also learn artifacts caused by the extraction protocol or alignment window. Its contribution should therefore be confirmed through shifted-window controls or external datasets constructed independently. Dinucleotide-stability features were retained only for Arabidopsis in the out-of-fold selection. This result suggests a possible contribution from local thermodynamic properties in the plant promoter dataset, but the evidence remains predictive rather than mechanistic.")
    body(doc, "The strongest feature-only development performance occurred in Arabidopsis, whereas B. subtilis was the weakest. Dataset size alone cannot fully explain this pattern: Arabidopsis was larger than B. subtilis, but the quality and regularity of the sequence signal, negative construction, and window definition also matter. The minimum MCC-improvement requirement of 0.002 reduced the risk of accepting negligible feature additions. Still, repeated feature comparisons can overfit development data. The final test evidence should remain centered on the prespecified hybrid models, and individual ablation gains should be presented as supportive analysis.")

    doc.add_heading("5.6 Why hybridization improved performance", level=1)
    body(doc, "The hybrid framework combined two distinct inductive biases. CNNs learn filters directly from ordered nucleotide matrices and can capture local motifs, interactions, and positional context without specifying which oligomers should matter. Random Forests operate on explicit summary features and divide feature space through nonlinear decision rules. A sequence misclassified by the CNN may still possess a characteristic k-mer profile recognized by the forest, while a promoter lacking a dominant global composition may be identified through localized neural activations. The positive MCC, ROC-AUC, and PR-AUC changes in every domain demonstrate that these error patterns were not completely redundant.")
    body(doc, "The mixture weights provide further insight. The bacterial hybrid retained 90% CNN weight and only 10% Random Forest weight, consistent with a limited but useful classical contribution. In contrast, Archaea and Eukaryota assigned 55% weight to the forest. The larger forest contribution does not mean the forest was universally superior; the weight was selected for its interaction with the averaged neural probability. Two individually imperfect predictors can form a better ensemble when their errors are complementary. The validation-selected weight is therefore a property of the pair, dataset, calibration, and threshold-selection procedure.")
    body(doc, "Hybridization also exposed trade-offs. In Bacteria and Archaea, sensitivity increased while specificity declined. In Eukaryota, both increased. The archaeal Brier score became worse even though ROC-AUC and PR-AUC improved, showing that discrimination and calibration are distinct. A model may rank positives more effectively yet produce probabilities that are less numerically calibrated. If the system were used for prioritizing laboratory candidates, ranking might be most important; if its probabilities were interpreted as risks or confidence values, calibration would require explicit attention through reliability analysis and potentially calibration methods fitted on development data.")

    doc.add_heading("5.7 Importance of leakage control and threshold selection", level=1)
    body(doc, "A major methodological strength was the prevention of exact-sequence and reverse-complement leakage. Promoter datasets frequently contain duplicates, closely related entries, or sequences represented in opposite orientations. If equivalent records appear in both training and test sets, performance can reflect memorization rather than generalizable promoter recognition. By assigning a canonical group identifier based on each sequence and its reverse complement, the study ensured that equivalent orientations remained in one partition. The quarantine of twelve archaeal records whose canonical groups appeared under both labels further prevented contradictory sequences from influencing training or evaluation.")
    body(doc, "Validation-only threshold selection was also essential. The optimal thresholds differed markedly: 0.876 for the bacterial neural ensemble, 0.598 for Archaea, and 0.560 for Eukaryota; the hybrid thresholds differed again. A universal 0.50 threshold would therefore have produced different sensitivity–specificity trade-offs and might have undervalued otherwise useful ranking models. Selecting thresholds by validation MCC aligned the operating point with a metric that uses every confusion-matrix component. Freezing each threshold before test evaluation preserved the test set as an independent assessment.")
    body(doc, "At the same time, threshold optimization makes the reported sensitivity and specificity dependent on the chosen objective. A practical screening system might prefer higher sensitivity to avoid missing true promoters, whereas a confirmatory annotation tool might prioritize precision and specificity to minimize false discoveries. The present MCC-based threshold represents a balanced research objective, not the only valid deployment choice. Future applications should define the cost of false negatives and false positives before selecting their operating point.")

    doc.add_heading("5.8 Biological and practical implications", level=1)
    body(doc, "From a biological perspective, the results support the view that promoter identity is encoded through multiple levels of sequence information. Short oligomer composition, motif orientation, relative position, and local stability each contributed in at least one organism, while convolutional models learned additional patterns directly from ordered nucleotide sequences. The success of multi-scale convolution for the shorter bacterial and archaeal windows suggests that promoter evidence occurs over multiple motif widths. The value of residual convolution and engineered features in Eukaryota indicates that longer promoter contexts benefit from combining learned local patterns with explicit global and positional summaries.")
    body(doc, "From a practical perspective, the final system can prioritize candidate promoter sequences and provide probabilities rather than only hard labels. Organism- or domain-specific routing is important because thresholds and mixture weights are not interchangeable. In a genome-annotation workflow, high-scoring predictions could be used to narrow the search space for experimental validation. The classifier should not be treated as proof of promoter activity, particularly for sequences from unrepresented organisms or environmental conditions. Promoter activity depends on cellular context, transcription-factor availability, chromatin state in eukaryotes, and experimental conditions that are not encoded in a short DNA window.")
    body(doc, "The high specificity and precision of the bacterial and eukaryotic systems may be beneficial when experimental validation is costly, because relatively few predicted positives are expected to be false. Conversely, their lower sensitivity means that absence of a positive prediction should not be interpreted as absence of promoter potential. The archaeal hybrid offered the most balanced operating profile and may be particularly effective for prioritization within datasets resembling its training sources. Generalization to other archaeal clades must still be tested because the current combined group represents only selected organisms.")

    doc.add_heading("5.9 Strengths of the study", level=1)
    for item in [
        "Broad taxonomic coverage incorporating bacterial, archaeal, mammalian, and plant promoter datasets.",
        "Use of curated positive sequences and biologically grounded genomic negative regions rather than purely artificial controls.",
        "Independent 90% redundancy reduction before modeling and a read-only audit of finalized FASTA files.",
        "Deterministic organism-and-class-stratified splitting with exact-sequence and reverse-complement grouping.",
        "Quarantine of cross-label conflicts instead of silently assigning contradictory records to model partitions.",
        "Use of MCC, PR-AUC, ROC-AUC, balanced accuracy, calibration, confusion matrices, and bootstrap intervals rather than accuracy alone.",
        "Multi-seed evaluation and validation-only selection of checkpoints, thresholds, feature blocks, and hybrid weights.",
        "Preservation of file hashes, source headers, manifests, configurations, probabilities, and model artifacts for reproducibility.",
    ]:
        bullet(doc, item)
    body(doc, "Together, these features increase confidence that the reported test results represent learnable sequence differences rather than simple duplication leakage or post-hoc adjustment to test labels. The study also separated primary confirmatory outcomes from supportive development analyses. This distinction is important in computational biology, where repeated experimentation on one benchmark can gradually transform an apparent test set into an informal validation set.")

    doc.add_heading("5.10 Limitations", level=1)
    body(doc, "The first limitation concerns dataset provenance and label certainty. Although the positive examples came from curated resources, database records vary in experimental support and annotation history. Genome-derived negatives can contain unannotated, condition-specific, or alternative promoters. The labels therefore represent the operational definitions used by the source datasets rather than absolute biological truth. In addition, the missing intermediate archaeal CD-HIT artifact prevents complete reproduction of one preprocessing transition, even though the finalized file was audited and used consistently.")
    body(doc, "Second, the study combined organisms at the domain-reporting level. Different species contributed unequal sample sizes, which means large datasets had greater influence on domain models and metrics. Eukaryota included two mammals and one plant, while Bacteria included only two model organisms. The aggregated archaeal group did not retain organism-specific modeling labels in the finalized pipeline. Domain performance should therefore not be generalized to all bacteria, archaea, animals, plants, fungi, or protists. In particular, no fungal species were represented despite their importance to eukaryotic promoter diversity.")
    body(doc, "Third, negative sampling protocols differed by domain. Bacterial negatives were derived from coding regions on the opposite strand, eukaryotic negatives came from downstream gene regions, and archaeal negatives were inherited from a published dataset. A classifier can potentially learn systematic differences introduced by source or extraction procedure. Independent external testing with consistently constructed negatives would help determine how much performance transfers beyond these protocols.")
    body(doc, "Fourth, the completed neural results covered selected specialist architectures, not an exhaustive comparison of all implemented candidates. The domain-aware unified model, CNN–BiLSTM, and CNN–Transformer were implemented but were not all subjected to the same complete multi-seed confirmatory evaluation. Consequently, the selected Multi-scale CNN and Residual CNN should be described as successful finalized configurations rather than universally optimal architectures. Formal paired comparisons, nested selection, and external validation remain necessary for stronger superiority claims.")
    body(doc, "Finally, model interpretation was limited. Feature ablation identified useful categories of information but did not identify specific causal promoter elements. Neural attention or convolutional activation is not automatically a biological explanation. Motif discovery, in-silico mutagenesis, attribution stability across seeds, positional enrichment, and comparison with established promoter elements would be needed to connect predictions to plausible regulatory mechanisms. Calibration also requires additional examination before probabilities are presented as quantitative confidence estimates in applied settings.")

    doc.add_heading("5.11 Recommendations for future work", level=1)
    body(doc, "Future research should first extend external and taxonomic validation. The trained models should be evaluated on independently curated promoter datasets, additional bacterial phyla, diverse archaeal lineages, fungi, non-model plants, and other animals. Leave-one-species-out experiments would provide a direct test of cross-species transfer. Where sufficient data are available, organism-level models should be compared with domain-shared and hierarchical multi-task systems under identical partitions and evaluation criteria.")
    body(doc, "A second priority is a complete architecture comparison. Residual CNN, Multi-scale CNN, CNN–BiLSTM, CNN–Transformer, and the proposed domain-aware model should each be trained across multiple seeds using a preregistered selection rule. Paired bootstrap or permutation comparisons should be conducted on predictions for the same test records. Hyperparameter selection should remain nested within development data, and the final external test set should be evaluated only after all choices are frozen.")
    body(doc, "Third, negative datasets should be strengthened through multiple biologically challenging controls. Potential strategies include matched genomic negatives with similar GC content, hard negatives drawn near but outside annotated promoter intervals, coding and intergenic negatives analyzed separately, dinucleotide-preserving shuffles used only as explicit controls, and cross-database negatives generated under a uniform procedure. Evaluating performance separately for each negative type would reveal whether a model recognizes promoters or merely distinguishes the construction protocol.")
    body(doc, "Fourth, interpretability should be expanded. In-silico mutagenesis can measure the effect of every nucleotide substitution; integrated gradients or related attribution methods can map influential positions; convolutional filters can be converted into candidate motifs; and motif enrichment can be compared across domains and species. Explanations should be tested for consistency across random seeds and validated against recognized promoter positions. Experimental follow-up of high-confidence novel predictions would provide the strongest evidence of biological relevance.")
    body(doc, "Finally, deployment-oriented evaluation should include probability calibration, decision-curve analysis, computational efficiency, and explicit operating thresholds for different applications. A high-sensitivity screening mode and a high-precision confirmation mode may be more useful than one universal threshold. The web predictor should display the model group, threshold, sequence-length requirements, and uncertainty warnings so that users understand the conditions under which a probability was produced.")

    doc.add_heading("5.12 Overall discussion", level=1)
    body(doc, "Overall, the findings support a domain-aware and hybrid view of promoter prediction. No single representation captured all useful information. Neural networks provided a flexible mechanism for learning ordered motif patterns; explicit sequence features contributed taxon-specific composition, orientation, position, and stability information; and multi-seed averaging reduced dependence on a single initialization. The strongest absolute performance occurred in Archaea, while Eukaryota obtained the clearest hybrid improvement. Bacteria remained the most difficult current domain, emphasizing the need for additional balanced data and organism-sensitive modeling.")
    body(doc, "The scientific contribution is not limited to the numerical performance values. Equally important is the leakage-aware experimental structure: redundancy-controlled inputs, reverse-complement grouping, quarantined label conflicts, fixed partitions, validation-only selection, untouched-test assessment, and saved artifacts. These controls make the findings more defensible and clarify which conclusions are established and which remain hypotheses. Within the limitations of dataset provenance, taxonomic coverage, and incomplete architecture comparison, the study provides evidence that combining specialized sequence learning with selected engineered features is an effective strategy for multi-domain promoter classification.")

    doc.add_heading("5.13 Chapter summary", level=1)
    body(doc, "This discussion interpreted the final promoter-prediction results in biological and computational terms. Archaeal promoters were classified most accurately in the present datasets, eukaryotic predictions benefited most from hybridization, and bacterial classification exhibited the greatest challenge and the most conservative neural threshold. Multi-seed probability averaging improved every domain, while organism-specific ablation demonstrated that useful sequence features were not universal. Hybrid models improved MCC and ranking measures throughout, although sensitivity, specificity, and calibration trade-offs differed. The results support domain-aware modeling and complementary representations, but external validation, broader species coverage, full architecture comparison, standardized negative construction, and mechanistic interpretation are required before universal claims can be made.")

    doc.core_properties.title = "Detailed Discussion Chapter"
    doc.core_properties.subject = "Discussion of domain-aware promoter prediction results"
    doc.save(OUTPUT)
    print(OUTPUT)


if __name__ == "__main__":
    build()
